using UnityEngine;
using UnityEngine.Tilemaps;

namespace IdleGrounds.Game
{
    /// <summary>
    /// A curved-coast cell (owner 2026-10-12: "round the corners into curves"): a cell the coastline crosses as one
    /// straight segment between two points on its edges. <see cref="geo"/> packs the land corners (bits 0-3: SW, SE, NW,
    /// NE) and the crossing position in px (0-32) on the S, E, N and W edges (6 bits each from bit 4). Neighbouring
    /// cells share their crossing points, so the outline is a continuous polyline that changes direction at every cell
    /// edge. Generated by the Editor (IslandCoastBuilder / CoastCurves); counts as land for <see cref="CoastRuleTile"/>.
    /// </summary>
    public class CoastShapeTile : Tile
    {
        [Tooltip("Packed geometry: land-corner mask | S << 4 | E << 10 | N << 16 | W << 22 (crossing px).")]
        public int geo;
    }
}
